var calc_output = [];

var a = isNaN(parseFloat(a)) ? 0 : parseFloat(a);
var hep = isNaN(parseFloat(hep)) ? 0 : parseFloat(hep);
var por = isNaN(parseFloat(por)) ? 0 : parseFloat(por);
var ren = isNaN(parseFloat(ren)) ? 0 : parseFloat(ren);

var grade = '';
var int = '';
var result = '';

// VExUS cascade logic
if (a == 1) {

    grade = 0;
    int = 'No apparent sign of congestion';
    result = 'Grade ' + grade;

} else if (a == 2 && hep != 0 && por != 0 && ren != 0) {

    var severeCount = 0;

    if (hep == 3) severeCount++;
    if (por == 3) severeCount++;
    if (ren == 3) severeCount++;

    if (severeCount >= 2) {
        grade = 3;
        int = 'Severe congestion';

    } else if (severeCount == 1) {
        grade = 2;
        int = 'Mild congestion';

    } else {
        grade = 1;
        int = 'No apparent sign of congestion';
    }

    result = 'Grade ' + grade;
}

// Output
calc_output.push({
    name: 'mini',
    value: result,
    value_text: '',
    message: int
});

calc_output.push({
    name: '10676_VExUS_result',
    value: result,
    value_text: '',
    message: 'VExUS'
});

